13	gkyl_gk_collisionless_flux*
14	gkyl_gk_collisionless_flux_new(const struct gkyl_rect_grid *phase_grid, 
15	  const struct gkyl_basis *conf_basis, const struct gkyl_basis *phase_basis, 
16	  const double charge, const double mass,
17	  enum gkyl_gk_collisionless_type type,
18	  const struct gk_geometry *gk_geom, const struct gkyl_dg_geom *dg_geom, 
19	  const struct gkyl_gk_dg_geom *gk_dg_geom, const struct gkyl_velocity_map *vel_map,
20	  const enum gkyl_gyrokinetic_bc_type *bctype_conf, bool use_gpu)
21	{
22	#ifdef GKYL_HAVE_CUDA
23	  if (use_gpu)
24	    return gkyl_gk_collisionless_flux_cu_dev_new(phase_grid, conf_basis, phase_basis,
25	      charge, mass, type, gk_geom, dg_geom, gk_dg_geom, vel_map, bctype_conf);
26	#endif     
27	
28	  gkyl_gk_collisionless_flux *up = gkyl_malloc(sizeof(gkyl_gk_collisionless_flux));
29	
30	  up->phase_grid = *phase_grid;
31	  int cdim = conf_basis->ndim;
32	  int pdim = phase_basis->ndim;
33	  int vdim = pdim - cdim;
34	  int poly_order = phase_basis->poly_order;
35	  up->cdim = cdim;
36	  up->pdim = pdim;
37	
38	  up->charge = charge;
39	  up->mass = mass;
40	
41	  up->gk_geom = gkyl_gk_geometry_acquire(gk_geom);
42	  up->dg_geom = gkyl_dg_geom_acquire(dg_geom);
43	  up->gk_dg_geom = gkyl_gk_dg_geom_acquire(gk_dg_geom);
44	  up->vel_map = gkyl_velocity_map_acquire(vel_map);
45	
46	  if (type == GKYL_GK_COLLISIONLESS_ES) {
47	    for (int d=0; d<cdim; ++d) {
48	      // BC option in ->flux_surf kernel doesn't matter as long as it's not SKIP.
49	      up->flux_surf[d] = choose_gk_collisionless_flux_surf_conf_kern(d, cdim, vdim, poly_order, GKYL_BC_GK_SPECIES_ABSORB);
50	      up->flux_surf_edge_lo[d] = choose_gk_collisionless_flux_surf_conf_kern(d, cdim, vdim,
51	        poly_order, bctype_conf[d]);
52	      up->flux_surf_edge_up[d] = choose_gk_collisionless_flux_edge_surf_conf_kern(d, cdim, vdim,
53	        poly_order, bctype_conf[GKYL_MAX_CDIM+d]);
54	    }
55	    up->flux_surfvpar[0] = choose_gk_collisionless_flux_surf_vpar_kern(cdim, vdim, poly_order);
56	  }
57	  else if (type == GKYL_GK_COLLISIONLESS_ES_NO_BY) {
58	    for (int d=0; d<cdim; ++d) {
59	      // BC option in ->flux_surf kernel doesn't matter as long as it's not SKIP.
60	      up->flux_surf[d] = choose_gk_collisionless_flux_no_by_surf_conf_kern(d, cdim, vdim, poly_order, GKYL_BC_GK_SPECIES_ABSORB);
61	      up->flux_surf_edge_lo[d] = choose_gk_collisionless_flux_no_by_surf_conf_kern(d, cdim, vdim,
62	        poly_order, bctype_conf[d]);
63	      up->flux_surf_edge_up[d] = choose_gk_collisionless_flux_no_by_edge_surf_conf_kern(d, cdim, vdim,
64	        poly_order, bctype_conf[GKYL_MAX_CDIM+d]);
65	    }
66	    up->flux_surfvpar[0] = choose_gk_collisionless_flux_no_by_surf_vpar_kern(cdim, vdim, poly_order);
67	  }
68	
69	  up->flags = 0;
70	  GKYL_CLEAR_CU_ALLOC(up->flags);
71	  up->on_dev = up; // self-reference on host
72	  
73	  return up;
74	}
75	
76	void gkyl_gk_collisionless_flux_surf(struct gkyl_gk_collisionless_flux *up, 
77	  const struct gkyl_range *conf_range, const struct gkyl_range *phase_range,
78	  const struct gkyl_range *conf_ext_range, const struct gkyl_range *phase_ext_range, const struct gkyl_array *phi, 
79	  const struct gkyl_array *fin, struct gkyl_array *yfield, struct gkyl_array* flux_surf, struct gkyl_array *cflrate)
80	{
81	#ifdef GKYL_HAVE_CUDA
82	  if (gkyl_array_is_cu_dev(flux_surf)) {
83	    return gkyl_gk_collisionless_flux_surf_cu(up, conf_range, phase_range,
84	      conf_ext_range, phase_ext_range, phi, fin, flux_surf, cflrate);
85	  }
86	#endif
87	  int pdim = up->pdim;
88	  int cdim = up->cdim;
89	  int idx[GKYL_MAX_DIM], idx_edge[GKYL_MAX_DIM], idx_vel[2];
90	  int idxL[GKYL_MAX_DIM];
91	  int idx_velL[2];
92	  double xc[GKYL_MAX_DIM];
93	
94	  struct gkyl_range vpar_range;
95	  int extend_lo[GKYL_MAX_DIM] = {0};
96	  int extend_up[GKYL_MAX_DIM] = {0};
97	  extend_lo[cdim] = -1;
98	  gkyl_range_extend(&vpar_range, phase_range, extend_lo, extend_up);
99	
100	  gkyl_array_clear(yfield, 0.0);
101	
102	  struct gkyl_range_iter iter;
103	  gkyl_range_iter_init(&iter, phase_range);
104	  while (gkyl_range_iter_next(&iter)) {
105	    gkyl_copy_int_arr(pdim, iter.idx, idx);
106	
107	    for (int d=cdim; d<pdim; d++) idx_vel[d-cdim] = iter.idx[d];
108	
109	    long loc_conf = gkyl_range_idx(conf_range, idx);
110	    long loc_vel = gkyl_range_idx(&up->vel_map->local_vel, idx_vel);
111	    long loc_phase = gkyl_range_idx(phase_range, idx);
112	
113	    gkyl_rect_grid_cell_center(&up->phase_grid, idx, xc);
114	
115	    const double *bmag_d = gkyl_array_cfetch(up->gk_geom->geo_corn.bmag, loc_conf);
116	    const double *vmap_d = gkyl_array_cfetch(up->vel_map->vmap, loc_vel);
117	    const double *vmapSq_d = gkyl_array_cfetch(up->vel_map->vmap_sq, loc_vel);
118	
119	    double *flux_surf_d = gkyl_array_fetch(flux_surf, loc_phase);
120	    double *cflrate_d = gkyl_array_fetch(cflrate, loc_phase);
121	
122	    for (int dir = 0; dir<cdim; ++dir) {
123	      gkyl_copy_int_arr(pdim, idx, idxL);
124	      idxL[dir] = idx[dir] - 1;
125	      long loc_confL = gkyl_range_idx(conf_range, idxL);
126	      long locL = gkyl_range_idx(phase_range, idxL);
127	      const double *fL = gkyl_array_cfetch(fin, locL);
128	      const double *fR = gkyl_array_cfetch(fin, loc_phase);
129	
130	      const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx);
131	      const struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx);
132	
133	      const double *jacgeo_rat_surfL_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_confL);
134	      const double *jacgeo_rat_surfR_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf);
135	
136	      const double *phiL_d = gkyl_array_cfetch(phi, loc_confL);
137	      const double *phiR_d = gkyl_array_cfetch(phi, loc_conf);
138	
139	      double *yfieldL = gkyl_array_fetch(yfield, locL);
140	      double *yfieldR = gkyl_array_fetch(yfield, loc_phase);
141	
142	      if (idx[dir] == phase_range->lower[dir]) {
143	        // Lower domain/block boundary.
144	        cflrate_d[0] += up->flux_surf_edge_lo[dir](xc, up->phase_grid.dx, vmap_d, vmapSq_d, up->charge, up->mass,
145	          dgs, gkdgs, bmag_d, jacgeo_rat_surfL_d, jacgeo_rat_surfR_d, phiL_d, phiR_d, fL, fR, yfieldL, yfieldR, flux_surf_d);
146	      } else {
147	        // Interior, lower cell surface.
148	        cflrate_d[0] += up->flux_surf[dir](xc, up->phase_grid.dx, vmap_d, vmapSq_d, up->charge, up->mass,
149	          dgs, gkdgs, bmag_d, jacgeo_rat_surfL_d, jacgeo_rat_surfR_d, phiL_d, phiR_d, fL, fR, yfieldL, yfieldR, flux_surf_d);
150	      }
151	
152	      // Upper domain/block boundary.
153	      // If the phase space index is at the local configuration space upper value, we
154	      // we are at the configuration space upper edge and we also need to evaluate 
155	      // alpha = +1 to avoid evaluating the geometry information in the ghost cells 
156	      // where it is not defined when computing the final surface alpha we need
157	      // (since the surface alpha array stores only the *lower* surface expansion)
158	      if (idx[dir] == phase_range->upper[dir]) {
159	        gkyl_copy_int_arr(pdim, idx, idx_edge);
160	        idx_edge[dir] = idx_edge[dir]+1;
161	        long loc_conf_ext = gkyl_range_idx(conf_ext_range, idx_edge);
162	        long loc_phase_ext = gkyl_range_idx(phase_ext_range, idx_edge);
163	
164	        double *cflrate_ext_d = gkyl_array_fetch(cflrate, loc_phase_ext);
165	
166	        const double *fL = gkyl_array_cfetch(fin, loc_phase);
167	        const double *fR = gkyl_array_cfetch(fin, loc_phase_ext);
168	
169	        const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx_edge);
170	        const struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx_edge);
171	
172	        const double *jacgeo_rat_surfL_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf);
173	        const double *jacgeo_rat_surfR_d = gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf_ext);
174	
175	        const double *phiL_d = gkyl_array_cfetch(phi, loc_conf);
176	        const double *phiR_d = gkyl_array_cfetch(phi, loc_conf_ext);
177	
178	        double *yfieldL = gkyl_array_fetch(yfield, loc_phase);
179	        double *yfieldR = gkyl_array_fetch(yfield, loc_phase_ext);
180	
181	        double* flux_surf_ext_d = gkyl_array_fetch(flux_surf, loc_phase_ext);
182	
183	        cflrate_ext_d[0] += up->flux_surf_edge_up[dir](xc, up->phase_grid.dx, vmap_d, vmapSq_d, up->charge, up->mass,
184	          dgs, gkdgs, bmag_d, jacgeo_rat_surfL_d, jacgeo_rat_surfR_d, phiL_d, phiR_d, fL, fR, yfieldL, yfieldR, flux_surf_ext_d);
185	      }  
186	    }
187	  }
188	
189	  gkyl_range_iter_init(&iter, &vpar_range);
190	  while (gkyl_range_iter_next(&iter)) {
191	    gkyl_copy_int_arr(pdim, iter.idx, idx);
192	
193	    for (int d=cdim; d<pdim; d++) idx_vel[d-cdim] = iter.idx[d];
194	
195	    long loc_conf = gkyl_range_idx(conf_range, idx);
196	    long loc_vel = gkyl_range_idx(&up->vel_map->local_vel, idx_vel);
197	    long loc_phase = gkyl_range_idx(phase_range, idx);
198	
199	    gkyl_rect_grid_cell_center(&up->phase_grid, idx, xc);
200	
201	    const double *bmag_d = gkyl_array_cfetch(up->gk_geom->geo_corn.bmag, loc_conf);
202	    const double *vmap_d = gkyl_array_cfetch(up->vel_map->vmap, loc_vel);
203	    const double *vmapSq_d = gkyl_array_cfetch(up->vel_map->vmap_sq, loc_vel);
204	    const double *yfield_d = gkyl_array_cfetch(yfield, loc_phase);
205	
206	    double *flux_surf_d = gkyl_array_fetch(flux_surf, loc_phase);
207	    double *cflrate_d = gkyl_array_fetch(cflrate, loc_phase);
208	
209	    int dir=cdim;
210	    gkyl_copy_int_arr(pdim, idx, idxL);
211	    idxL[dir] = idx[dir] - 1;
212	    gkyl_copy_int_arr(pdim-cdim, idx_vel, idx_velL);
213	    idx_velL[0] = idx_velL[0]-1;
214	    long locL = gkyl_range_idx(phase_range, idxL);
215	    long loc_velL = gkyl_range_idx(&up->vel_map->local_vel, idx_velL);
216	    const double *fL = gkyl_array_cfetch(fin, locL);
217	    const double *fR = gkyl_array_cfetch(fin, loc_phase);
218	
219	    const double *vpL = gkyl_array_cfetch(up->vel_map->vmap_prime, loc_velL);
220	    const double *vpR = gkyl_array_cfetch(up->vel_map->vmap_prime, loc_vel);
221	
222	    const struct gkyl_dg_vol_geom *dgv = gkyl_dg_geom_get_vol(up->dg_geom, idx);
223	    const struct gkyl_gk_dg_vol_geom *gkdgv = gkyl_gk_dg_geom_get_vol(up->gk_dg_geom, idx);
224	    cflrate_d[0] += up->flux_surfvpar[0](xc, up->phase_grid.dx, vpL, vpR, vmap_d, vmapSq_d, up->charge, up->mass,
225	      dgv, gkdgv, bmag_d, yfield_d, fL, fR, flux_surf_d);
226	  }
227	}
228	
229	void gkyl_gk_collisionless_flux_release(gkyl_gk_collisionless_flux *up)
230	{
231	  gkyl_gk_geometry_release(up->gk_geom);
232	  gkyl_dg_geom_release(up->dg_geom);
233	  gkyl_gk_dg_geom_release(up->gk_dg_geom);
234	  gkyl_velocity_map_release(up->vel_map);
235	  
236	  if (GKYL_IS_CU_ALLOC(up->flags))
237	    gkyl_cu_free(up->on_dev);
238	  gkyl_free(up);
239	}
